use symbolica::{atom::Atom, domains::rational::{Q,Rational}, poly::univariate::UnivariatePolynomial};
fn main(){
 let v=Atom::parse("x","plan36",Default::default()).unwrap(); let symbolica::atom::AtomView::Var(x)=v.as_view() else {panic!()};
 let cases: [(&str,[f64;4],usize);7]=[("three",[-6.,11.,-6.,1.],3),("one",[-1.,0.,0.,1.],1),("triple",[-1.,3.,-3.,1.],1),("quadratic",[-1.,0.,1.,0.],2),("linear",[-2.,1.,0.,0.],1),("near-critical",[0.,-2f64.powi(-60),0.,1.],3),("zero-root",[0.,1.,0.,0.],1)];
 for (name,c,count) in cases {let poly=UnivariatePolynomial::from_coefficients(&Q,c.into_iter().map(|c|Rational::try_from(c).unwrap()).collect(),std::sync::Arc::new(symbolica::poly::PolyVariable::Symbol(x.get_symbol())));let roots=poly.isolate_real_root_intervals(); assert_eq!(roots.len(),count); let old=poly.isolate_real_roots();assert_eq!(roots.len(),old.len());assert_eq!(roots.iter().map(|r|r.2).sum::<usize>(),old.iter().map(|r|r.1).sum::<usize>()); println!("cubic {} distinct={} multiplicity={}",name,roots.len(),roots.iter().map(|r|r.2).sum::<usize>());for(a,b,_)in roots {if a!=b && (poly.evaluate(&a).is_zero() || poly.evaluate(&b).is_zero()){println!("guarded exact fallback {} endpoint-root",name);continue;}let interval=poly.refine_root_interval((a,b),&Rational::from((1,1i64<<54)));let mid=(&interval.0+&interval.1)/Rational::from(2); assert!(mid.to_f64().is_finite());}}
 for n in [128usize,512] {
  use faer::{sparse::{Triplet,SparseColMat,linalg::lu},dyn_stack::{MemBuffer,MemStack},Par,Conj,Mat};
  let mut entries=Vec::new();for i in 0..n{entries.push(Triplet::new(i,i,4.0));if i>0{entries.push(Triplet::new(i,i-1,-1.0));}if i+1<n{entries.push(Triplet::new(i,i+1,-1.0));}}
  let a=SparseColMat::try_new_from_triplets(n,n,&entries).unwrap();let symbolic=lu::factorize_symbolic_lu(a.symbolic(),Default::default()).unwrap();let req=symbolic.factorize_numeric_lu_scratch::<f64>(Par::Seq,Default::default());let mut memory=MemBuffer::new(req);let mut numeric=lu::NumericLu::new();symbolic.factorize_numeric_lu(&mut numeric,a.as_ref(),Par::Seq,MemStack::new(&mut memory),Default::default()).unwrap();let reqsolve=symbolic.solve_in_place_scratch::<f64>(2,Par::Seq);let mut memsolve=MemBuffer::new(reqsolve);let expected=Mat::from_fn(n,2,|i,j|(i+1+j)as f64);let mut rhs=Mat::zeros(n,2);faer::sparse::linalg::matmul::sparse_dense_matmul(rhs.as_mut(),faer::Accum::Replace,a.as_ref(),expected.as_ref(),1.0,Par::Seq);let l=lu::LuRef::new_unchecked(&symbolic,&numeric);l.solve_in_place_with_conj(Conj::No,rhs.as_mut(),Par::Seq,MemStack::new(&mut memsolve));let maxerr=(0..n).flat_map(|i|(0..2).map(move|j|(i,j))).map(|(i,j)|(rhs[(i,j)]-expected[(i,j)]).abs()).fold(0.0,f64::max);assert!(maxerr<1e-10);println!("sparse n={} nnz={} factor_scratch={} solve2_scratch={} error={}",n,entries.len(),req.size_bytes(),reqsolve.size_bytes(),maxerr);
 }
 let a=faer::mat![[1.0_f64,1.],[0.,2f64.powi(-30)]];let s=a.svd().unwrap();let sigma=s.S().column_vector(); let qr=a.col_piv_qr();let r=qr.R();let tau=0.75*2f64.powi(-30);let sr=sigma.iter().filter(|s|**s>tau*sigma[0]).count();let qrmax=r[(0,0)].abs().max(r[(1,1)].abs());let qr_rank=(0..2).filter(|i|r[(*i,*i)].abs()>tau*qrmax).count();assert_eq!((sr,qr_rank),(1,2));println!("rank comparison sigma={:?} qrdiag=[{},{}]",sigma,r[(0,0)].abs(),r[(1,1)].abs());
}
